"use strict";

// Expected values were generated by independently executing the original ARM64
// IL2CPP/Unity/Android libm images, not this implementation. The adjacent fixture
// provenance identifies every image, original entrypoint and runtime boundary.
const assert = require("assert");
const fs = require("fs");
const path = require("path");
const staticRoot = path.resolve(__dirname, "../webtools/web/static");
const THREE = require(path.join(staticRoot, "vendor/three-r128/three.min.js"));
require(path.join(staticRoot, "viewer-game-physics-math.js"));
require(path.join(staticRoot, "viewer-game-physics-collision.js"));
require(path.join(staticRoot, "viewer-game-physics.js"));
const reference = global.ViewerGamePhysics.reference;
const math = global.ViewerGamePhysicsMath;
const load = name => JSON.parse(fs.readFileSync(path.join(__dirname, "fixtures", name), "utf8"));
const jobs = load("game_physics_native_jobs.json");
const safe = load("game_physics_native_safe_correct.json");
assert.strictEqual(jobs.provenance.solverStubs, 0);
assert.strictEqual(jobs.provenance.quaternionStubs, 0);
assert.strictEqual(safe.provenance.solverMathStubs, 0);
assert.deepStrictEqual(Object.keys(jobs.provenance.images).sort(), ["android26_libm", "il2cpp", "libunity"]);
const copy = value => Array.isArray(value) ? value.map(copy) : value && typeof value === "object"
  ? Object.fromEntries(Object.entries(value).map(([key, item]) => [key, copy(item)])) : value;
const fields = ["parentPosition", "parentRotation", "position", "rotation", "localRotation", "previousTipPosition", "currentTipPosition"];
const scratch = new DataView(new ArrayBuffer(4));
function floatFromBits(hex) { scratch.setUint32(0, parseInt(hex, 16), true); return scratch.getFloat32(0, true); }
function bits(value) { scratch.setFloat32(0, value, true); return scratch.getUint32(0, true); }
const tolerance = 2e-5;
let components = 0, exactComponents = 0, maximumAbsoluteError = 0;
function compare(actual, expected, context) {
  assert.strictEqual(actual.length, expected.length, context + " shape");
  actual.forEach((value, index) => {
    const error = Math.abs(value - expected[index]);
    components++;
    if (bits(value) === bits(expected[index])) exactComponents++;
    maximumAbsoluteError = Math.max(maximumAbsoluteError, error);
    assert(Number.isFinite(value) && Number.isFinite(expected[index]) && error <= tolerance,
      `${context}[${index}]: ${value} differs from original ${expected[index]} by ${error}`);
  });
}
let jobFrames = 0;
for (const fixture of jobs.cases) {
  const buffers = copy(fixture.buffers), data = copy(fixture.data);
  const colliderData = copy(fixture.colliderData), matrices = copy(fixture.matrices);
  for (let frame = 0; frame < fixture.expected.length; frame++) {
    if (fixture.refresh && fixture.refresh[frame]) {
      fixture.refresh[frame].forEach((changes, boneIndex) => {
        for (const field of fields) if (Object.prototype.hasOwnProperty.call(changes, field))
          buffers[boneIndex][field] = changes[field].slice();
      });
    }
    reference.stepJob(data, buffers, colliderData, matrices,
      {kind:fixture.profile, epsilon:floatFromBits(fixture.epsilonBits), math});
    fixture.expected[frame].forEach((native, boneIndex) => {
      for (const field of fields)
        compare(buffers[boneIndex][field], native[field], `${fixture.name}/${fixture.profile}/frame${frame}/bone${boneIndex}/${field}`);
    });
    jobFrames++;
  }
}
assert(jobs.cases.some(c => c.name === "group-offset-sibling-capsules" && c.profile === "group"));
assert(jobs.cases.some(c => c.name === "animated-captured-pose-refresh"));
assert(jobs.cases.some(c => c.name === "pure-collision-child-capsule-sphere-stored-pivot"));
const jobMetrics = {cases:jobs.cases.length, frames:jobFrames, components, exactComponents, maximumAbsoluteError};
components = 0; exactComponents = 0; maximumAbsoluteError = 0;
let safeFrames = 0;
for (const fixture of safe.cases) {
  const input = fixture.input;
  const state = Object.assign(copy(input.fields), {length:input.fields.springLength,
    pivot:input.bonePosition.slice(), rotation:input.boneRotation.slice(), childPosition:input.childPosition.slice(),
    parentForward:input.parentForward.slice(), parentMatrix:input.parentMatrix.slice()});
  fixture.expected.forEach((native, frame) => {
    const corrected = reference.safeCorrect(state, input.kneeL, input.kneeR, input.forceCorrect, math, THREE);
    const context = `${fixture.name}/frame${frame}`;
    assert.strictEqual(Boolean(corrected), native.corrected, context + " native setter branch");
    assert.strictEqual(Boolean(state.safeCorrectAdjust), native.safeCorrectAdjust, context + " adjust flag");
    compare([state.skirtRotRatio], [native.skirtRotRatio], context + "/skirtRotRatio");
    compare(state.rotation, native.rotation, context + "/rotation");
    compare(state.childPosition, native.childPosition, context + "/childPosition");
    safeFrames++;
  });
}
assert(safe.cases.some(c => c.name === "no-contact-preserves-prior-adjust" && c.expected[0].safeCorrectAdjust && !c.expected[0].corrected));
assert(safe.cases.some(c => c.name === "ratio-zero-corrects-behind-plane" && c.expected[0].skirtRotRatio === 0 && c.expected[0].corrected));
console.log(JSON.stringify({status:"PASS", originalJobs:jobMetrics,
  originalSafeCorrect:{cases:safe.cases.length,frames:safeFrames,components,exactComponents,maximumAbsoluteError},
  tolerance, note:"Ordinary JS transcendental rounding is bounded against the documented ARM64 Android libm reference."}));
